/*
 * Weather Station with TFT Dashboard + Air Quality
 *
 * Wiring:
 *   BME280:  VCC->5V  GND->GND  SCL->A5  SDA->A4
 *   MQ-2:    VCC->5V  GND->GND  A0->A0
 *   ILI9341: VCC->5V  GND->GND  CS->D10  DC->D9  MOSI->D11  SCK->D13
 *
 * Drag the sliders on BME280 and MQ-2 to simulate conditions.
 */

#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_ILI9341.h>
#include <SimpleBME280.h>

#define TFT_CS 10
#define TFT_DC 9

Adafruit_ILI9341 tft(TFT_CS, TFT_DC);
SimpleBME280 bme;

const int gasPin = A0;

#define NAVY    0x001F
#define DARKCYAN 0x03EF
#define CYAN    0x07FF
#define YELLOW  0xFFE0
#define GREEN   0x07E0
#define RED     0xF800
#define ORANGE  0xFD20
#define WHITE   0xFFFF
#define BLACK   0x0000
#define GRAY    0x8410

void drawHeader() {
  tft.fillScreen(NAVY);
  tft.drawRect(5, 5, 310, 230, DARKCYAN);
  tft.drawRect(8, 8, 304, 224, 0x02B0);
  tft.setTextColor(YELLOW);
  tft.setTextSize(2);
  tft.setCursor(20, 18);
  tft.println("Weather Station");
  tft.setTextColor(WHITE);
  tft.setTextSize(1);
  tft.setCursor(20, 40);
  tft.println("BME280 + MQ-2 Air Quality");
}

void setup() {
  Serial.begin(115200);
  Wire.begin();
  bme.begin();
  tft.begin();
  tft.setRotation(1);
  drawHeader();
  Serial.println("Weather Station + Air Quality (TFT)");
  Serial.println("-----------------------------------");
}

void loop() {
  float tempC  = bme.readTemperature();
  float humPct = bme.readHumidity();
  float presPa = bme.readPressure();
  int gasRaw   = analogRead(gasPin);

  Serial.print("Temp:     "); Serial.print(tempC, 1); Serial.println(" C");
  Serial.print("Humidity: "); Serial.print(humPct, 1); Serial.println(" %");
  Serial.print("Pressure: "); Serial.print(presPa / 100.0, 1); Serial.println(" hPa");
  Serial.print("Air Qual: "); Serial.print(gasRaw);
  if (gasRaw < 200) Serial.println(" (Good)");
  else if (gasRaw < 400) Serial.println(" (Moderate)");
  else if (gasRaw < 600) Serial.println(" (Poor)");
  else Serial.println(" (Hazardous)");
  Serial.println("-----------------------------------");

  tft.fillRect(15, 55, 290, 170, NAVY);

  // Temperature
  tft.setTextColor(CYAN);
  tft.setTextSize(1);
  tft.setCursor(20, 65);
  tft.print("TEMPERATURE");
  tft.setTextColor(WHITE);
  tft.setTextSize(3);
  tft.setCursor(20, 80);
  tft.print(tempC, 1);
  tft.setTextSize(2);
  tft.print(" C");

  // Humidity
  tft.setTextColor(CYAN);
  tft.setTextSize(1);
  tft.setCursor(200, 65);
  tft.print("HUMIDITY");
  tft.setTextColor(WHITE);
  tft.setTextSize(3);
  tft.setCursor(200, 80);
  tft.print((int)humPct);
  tft.setTextSize(2);
  tft.print(" %");

  // Pressure
  tft.setTextColor(CYAN);
  tft.setTextSize(1);
  tft.setCursor(20, 120);
  tft.print("PRESSURE");
  tft.setTextColor(WHITE);
  tft.setTextSize(3);
  tft.setCursor(20, 135);
  tft.print((int)(presPa / 100.0));
  tft.setTextSize(2);
  tft.print(" hPa");

  // Air Quality
  tft.setTextColor(ORANGE);
  tft.setTextSize(1);
  tft.setCursor(200, 120);
  tft.print("AIR QUALITY");

  uint16_t gasColor;
  const char* gasLabel;
  if (gasRaw < 200) { gasColor = GREEN; gasLabel = "GOOD"; }
  else if (gasRaw < 400) { gasColor = YELLOW; gasLabel = "MODERATE"; }
  else if (gasRaw < 600) { gasColor = ORANGE; gasLabel = "POOR"; }
  else { gasColor = RED; gasLabel = "HAZARDOUS"; }

  tft.setTextColor(gasColor);
  tft.setTextSize(3);
  tft.setCursor(200, 135);
  tft.print(gasRaw);

  tft.setTextSize(2);
  tft.setCursor(200, 165);
  tft.print(gasLabel);

  // Gas level bar
  tft.drawRect(20, 180, 280, 16, GRAY);
  int barW = map(gasRaw, 0, 1023, 0, 278);
  tft.fillRect(21, 181, barW, 14, gasColor);

  delay(2000);
}
